package qe

// Source: src/qe/qe.cpp and qe_arith_plugin.cpp, equation solving subset.

import (
	"errors"

	"github.com/glycerine/g3/pkg/ast"
	"github.com/glycerine/g3/pkg/ast/rewriter"
	"github.com/glycerine/g3/pkg/tactic"
)

func solveQuantifierArithmeticEquation(m *ast.ASTManager, variables []ast.ASTHandle, formula ast.ASTHandle) (result *ArithmeticEquationElimination, solved bool, err error) {
	defer func() {
		if err != nil && result != nil {
			err = errors.Join(err, result.Close())
			result = nil
			solved = false
		}
	}()
	context, err := NewSolverContext(m, variables)
	if err != nil {
		return nil, false, err
	}
	defer func() { err = errors.Join(err, context.Close()) }()
	plugin, err := NewArithmeticPlugin(context)
	if err != nil {
		return nil, false, err
	}
	defer func() { err = errors.Join(err, plugin.Close()) }()
	conjs, err := NewConjunctionEnum(m, formula)
	if err != nil {
		return nil, false, err
	}
	defer func() { err = errors.Join(err, conjs.Close()) }()
	solved, err = plugin.Solve(conjs, formula)
	if err != nil || !solved {
		return nil, solved, err
	}
	result, err = plugin.TakeEquationElimination()
	if err == nil && result == nil {
		err = ast.ErrASTDomain
	}
	return result, err == nil, err
}

// eliminateQuantifierArithmeticEquations handles quantifiers whose arithmetic
// declarations can all be removed by existing equation solving. Fresh
// variables generated by integer elimination are processed in source order.
func eliminateQuantifierArithmeticEquations(m *ast.ASTManager, quantifier ast.ASTHandle, config Config) (result ast.ASTRef, complete bool, err error) {
	if m == nil || config.Cooperation == nil {
		return result, false, ast.ErrASTHandle
	}
	defer func() {
		if err != nil && result != (ast.ASTRef{}) {
			err = errors.Join(err, m.DelRef(&result))
		}
	}()
	kind, err := m.GetKind(quantifier)
	if err != nil || kind != ast.ASTQuantifier {
		return result, false, err
	}
	free, err := rewriter.NewExprFreeVars(m)
	if err != nil {
		return result, false, err
	}
	if err = free.Collect(quantifier); err != nil || !free.Empty() {
		return result, false, err
	}
	body, err := m.GetQuantifierBody(quantifier)
	if err != nil {
		return result, false, err
	}
	nested, err := m.HasQuantifiers(body)
	if err != nil || nested {
		return result, false, err
	}
	family, err := m.ArithmeticFamilyID()
	if err != nil {
		return result, false, err
	}
	count, err := m.GetNumDeclarations(quantifier)
	if err != nil {
		return result, false, err
	}
	for i := uint32(0); i < count; i++ {
		sort, e := m.GetDeclarationSort(quantifier, i)
		if e != nil {
			return result, false, e
		}
		sortFamily, e := m.GetFamilyID(sort)
		if e != nil || sortFamily != family {
			return result, false, e
		}
	}
	extracted, err := extractExprQuantifier(m, quantifier)
	if err != nil {
		return result, false, closeFailedExprQuantifierExtract(extracted, err)
	}
	defer func() { err = errors.Join(err, extracted.Close()) }()
	var auxiliary []ast.ASTRef
	defer func() {
		for i := len(auxiliary) - 1; i >= 0; i-- {
			err = errors.Join(err, m.DelRef(&auxiliary[i]))
		}
	}()
	variables := make([]ast.ASTHandle, len(extracted.variables))
	for i, ref := range extracted.variables {
		variables[i], err = m.RefGet(ref)
		if err != nil {
			return result, false, err
		}
	}
	rw, err := rewriter.NewTheoryRewriter(m, config.Context, config.Globals, nil)
	if err != nil {
		if rw != nil {
			err = errors.Join(err, rw.Close())
		}
		return result, false, err
	}
	defer func() { err = errors.Join(err, rw.Close()) }()
	body, err = m.RefGet(extracted.body)
	if err != nil {
		return result, false, err
	}
	forall, err := m.IsForall(quantifier)
	if err != nil {
		return result, false, err
	}
	if forall {
		body, err = m.MkNot(body)
		if err != nil {
			return result, false, err
		}
	}
	formula, err := m.NewRef(body)
	if err != nil {
		return result, false, err
	}
	defer func() { err = errors.Join(err, m.DelRef(&formula)) }()
	for len(variables) != 0 {
		canceled, e := m.Canceled()
		if e != nil {
			return result, false, e
		}
		if canceled {
			return result, false, tactic.NewTacticException(m.ResourceLimit().CancelMessage())
		}
		if err = config.Cooperation.Cooperate("qe"); err != nil {
			return result, false, err
		}
		body, err = m.RefGet(formula)
		if err != nil {
			return result, false, err
		}
		if err = rw.Rewrite(body, formula); err != nil {
			return result, false, err
		}
		body, err = m.RefGet(formula)
		if err != nil {
			return result, false, err
		}
		removed := false
		for i, variable := range variables {
			contains, e := ast.NewContainsApp(m, variable)
			if e != nil {
				return result, false, e
			}
			found, e := contains.Check(body)
			e = errors.Join(e, contains.Close())
			if e != nil {
				return result, false, e
			}
			if !found {
				variables = append(variables[:i], variables[i+1:]...)
				removed = true
				break
			}
		}
		if removed {
			continue
		}
		equation, solved, e := solveQuantifierArithmeticEquation(m, variables, body)
		if e != nil || !solved {
			return result, false, e
		}
		if equation.VariableIndex >= uint32(len(variables)) {
			return result, false, errors.Join(ast.ErrASTDomain, equation.Close())
		}
		index := equation.VariableIndex
		next, e := m.RefGet(equation.Formula)
		if e == nil {
			e = m.SetRef(formula, next)
		}
		variables = append(variables[:index], variables[index+1:]...)
		for i := len(equation.Fresh) - 1; e == nil && i >= 0; i-- {
			var ref ast.ASTRef
			ref, e = m.CopyRef(equation.Fresh[i])
			if e != nil {
				break
			}
			auxiliary = append(auxiliary, ref)
			var variable ast.ASTHandle
			variable, e = m.RefGet(ref)
			if e == nil {
				variables = append(variables, variable)
			}
		}
		e = errors.Join(e, equation.Close())
		if e != nil {
			return result, false, e
		}
	}
	body, err = m.RefGet(formula)
	if err != nil {
		return result, false, err
	}
	if forall {
		body, err = m.MkNot(body)
		if err != nil {
			return result, false, err
		}
	}
	result, err = m.NewRef(body)
	if err != nil {
		return result, false, err
	}
	if err = rw.Rewrite(body, result); err != nil {
		return result, false, err
	}
	return result, true, nil
}
